%[text] # Singular Value Decomposition Workshop
%[text] Explore the singular value decomposition through geometry, computation, and teaching design. This plain-text live script targets MATLAB R2025b and is written for educators who teach linear algebra and want to see the kinds of interactive activities they can build with MATLAB Live Scripts and MATLAB Copilot.
%[text:tableOfContents]{"heading":"Contents"}
%[text] - workshop goals
%[text] - geometry of the SVD
%[text] - properties worth testing
%[text] - a student checkpoint pattern
%[text] - low-rank approximation
%[text] - image compression with SVD
%[text] - teaching with live scripts and Copilot
%[text] - build your own adaptation \
%%
%[text] ## Workshop Goals
%[text] This activity is designed for a 30-minute walk-through. It gives educators a compact example of an SVD lesson that mixes explanation, computation, visualization, self-checks, and prompts for lesson authoring.
%[text] By the end of the script, participants should be able to explain the factorization $ A = U\\Sigma V^T $, connect singular values to stretching, interpret rank and energy capture, and identify at least one teaching activity they could build for their own students.
%[text] 1. Minutes 0-5: preview the structure and learning goals.
%[text] 2. Minutes 5-12: connect $ U $, $ \\Sigma $, and $ V $ to geometry.
%[text] 3. Minutes 12-18: inspect algebraic properties and a self-checking task.
%[text] 4. Minutes 18-24: use low-rank approximation and image compression as an application story.
%[text] 5. Minutes 24-30: adapt the template into a new classroom activity \
rng(7)
%%
%[text] ## Geometry of the SVD
%[text] A useful story for students is that the SVD applies three steps in sequence: rotate or reflect with $ V^T $, stretch along perpendicular directions with $ \\Sigma $, and rotate or reflect again with $ U $.
%[text] The next plot starts with the unit circle, then shows how one matrix turns it into an ellipse. This is often the fastest route to geometric intuition.
A = [3 1; 0 2];
[U,S,V] = svd(A);
theta = linspace(0,2*pi,400);
unitCircle = [cos(theta); sin(theta)];
midShape = S*(V'*unitCircle);
finalShape = U*midShape;
tiledlayout(1,3) %[output:012ccea4]
nexttile %[output:012ccea4]
plot(unitCircle(1,:),unitCircle(2,:),'k','LineWidth',1.5) %[output:012ccea4]
hold on %[output:012ccea4]
quiver(0,0,V(1,1),V(2,1),0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:012ccea4]
quiver(0,0,V(1,2),V(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:012ccea4]
axis equal %[output:012ccea4]
grid on %[output:012ccea4]
title('Input space') %[output:012ccea4]
xlabel('x_1') %[output:012ccea4]
ylabel('x_2') %[output:012ccea4]
legend('unit circle','v_1','v_2','Location','southoutside') %[output:012ccea4]
nexttile %[output:012ccea4]
plot(midShape(1,:),midShape(2,:),'k','LineWidth',1.5) %[output:012ccea4]
hold on %[output:012ccea4]
quiver(0,0,S(1,1),0,0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:012ccea4]
quiver(0,0,0,S(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:012ccea4]
axis equal %[output:012ccea4]
grid on %[output:012ccea4]
title('After V^T and Sigma') %[output:012ccea4]
xlabel('e_1') %[output:012ccea4]
ylabel('e_2') %[output:012ccea4]
nexttile %[output:012ccea4]
plot(finalShape(1,:),finalShape(2,:),'k','LineWidth',1.5) %[output:012ccea4]
hold on %[output:012ccea4]
quiver(0,0,S(1,1)*U(1,1),S(1,1)*U(2,1),0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:012ccea4]
quiver(0,0,S(2,2)*U(1,2),S(2,2)*U(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:012ccea4]
axis equal %[output:012ccea4]
grid on %[output:012ccea4]
title('Output space') %[output:012ccea4]
xlabel('y_1') %[output:012ccea4]
ylabel('y_2') %[output:012ccea4]
%%
%[text] ## Properties Worth Testing
%[text] In a classroom activity, this is a natural place to pause and ask students what should always be true after computing an SVD.
%[text] The table below checks reconstruction, orthogonality, rank, and the best rank-1 approximation error for a second matrix.
% Create a 3x3 matrix with one large singular value and two smaller ones
% Specify desired singular values
S = diag([100, 1, 0.5]); % large singular value 100, smaller 1 and 0.5

% Create random orthogonal matrices U and V via QR
[U,~] = qr(randn(3));
[V,~] = qr(randn(3));

% Ensure proper rotation (determinant +1) if desired
if det(U) < 0, U(:,1) = -U(:,1); end
if det(V) < 0, V(:,1) = -V(:,1); end

% Construct matrix with specified singular values
B = U * S * V';
% Compute the singular value decomposition of the matrix A
[U_A, S_A, V_A] = svd(B);

%B = [4 0 3; 1 -2 0; 2 1 1];
[UB,SB,VB] = svd(B);
s = diag(SB);
rank1Approx = lowRankApprox(UB,SB,VB,1);
propertyTable = table(["Reconstruction error ||B-USV^T||_F"; "Orthogonality error of U"; "Orthogonality error of V"; "Rank of B"; "Best rank-1 error in the 2-norm"], [norm(B - UB*SB*VB','fro'); norm(UB'*UB - eye(size(UB,2)),'fro'); norm(VB'*VB - eye(size(VB,2)),'fro'); rank(B); norm(B - rank1Approx,2)], 'VariableNames', ["Property","Value"]) %[output:23803d78]
energyCaptured = cumsum(s.^2)/sum(s.^2);
singularValueTable = table((1:numel(s)).', s, energyCaptured, 'VariableNames', ["Index","SingularValue","CumulativeEnergy"]) %[output:8499e92f]
%[text] Discussion prompt: Which quantities are exact in theory, which are approximate in floating-point arithmetic, and how would you want students to explain the difference?
%%
%[text] ## A Student Checkpoint Pattern
%[text] Live scripts can include short answer checks that keep students active while still preserving mathematical interpretation. Replace the `NaN` values below to simulate what a student would do.
%[text] Ask participants to predict each answer before they run the checker. This models how a Live Script can behave like a guided worksheet instead of a static handout.
studentRank = 3;
studentEnergyAt2 = 1;
studentBestRank1Error = s(2);
checkScalar("Rank of B", studentRank, rank(B)) %[output:8ca66e19]
checkScalar("Energy captured by the first two singular values", studentEnergyAt2, energyCaptured(2), 1e-4) %[output:42e746f2]
checkScalar("Best rank-1 error in the 2-norm", studentBestRank1Error, s(2), 1e-4) %[output:935499c7]
%%
%[text] ## Low-Rank Approximation
%[text] Low-rank approximation connects the SVD to applications students recognize quickly: compression, denoising, latent structure, and feature extraction.
%[text] For an $ m \\times n $ matrix, a rank-$ r $ SVD model stores about $ r(m+n+1) $ numbers instead of $ mn $. That tradeoff gives educators a natural bridge from theory to data science and scientific computing.
M = peaks(120);
[UM,SM,VM] = svd(M);
candidateRanks = [1 2 5 10];
relativeErrors = zeros(size(candidateRanks));
for k = 1:numel(candidateRanks)
    relativeErrors(k) = norm(M - lowRankApprox(UM,SM,VM,candidateRanks(k)),'fro')/norm(M,'fro');
end
compressionTable = table(candidateRanks.', relativeErrors.', (candidateRanks.*(size(M,1) + size(M,2) + 1)/numel(M)).', 'VariableNames', ["Rank","RelativeFrobeniusError","StorageFraction"]) %[output:6130bbd6]
tiledlayout(2,3) %[output:45df3498]
nexttile %[output:45df3498]
imagesc(M) %[output:45df3498]
axis image off %[output:45df3498]
title('Original matrix') %[output:45df3498]
colorbar %[output:45df3498]
for k = 1:numel(candidateRanks)
    nexttile %[output:45df3498]
    imagesc(lowRankApprox(UM,SM,VM,candidateRanks(k)))
    axis image off
    title("Rank " + candidateRanks(k))
    colorbar
end
nexttile %[output:45df3498]
semilogy(diag(SM),'o-','LineWidth',1.5) %[output:45df3498]
grid on %[output:45df3498]
title('Singular value decay') %[output:45df3498]
xlabel('index') %[output:45df3498]
ylabel('sigma_i') %[output:45df3498]
%%
%[text] ## Image Compression With SVD
%[text] Image compression is often the application that makes the SVD feel immediately relevant to students. A grayscale image is just a matrix, and a rank-$ r $ approximation keeps only the largest singular-value directions.
%[text] This section uses MATLAB's sample `cameraman.tif` image so the activity stays self-contained. The main teaching question is not just whether the image still looks acceptable, but how much information was discarded to make that happen.
imageData = im2double(imread('cameraman.tif'));
[Ui,Si,Vi] = svd(imageData);
imageRanks = [5 15 40 80];
imageErrors = zeros(size(imageRanks));
imageStorage = zeros(size(imageRanks));
tiledlayout(2,3) %[output:7f7f3b63]
nexttile %[output:7f7f3b63]
imagesc(imageData) %[output:7f7f3b63]
axis image off %[output:7f7f3b63]
colormap gray %[output:7f7f3b63]
title('Original image') %[output:7f7f3b63]
colorbar %[output:7f7f3b63]
for k = 1:numel(imageRanks)
    compressedImage = lowRankApprox(Ui,Si,Vi,imageRanks(k));
    imageErrors(k) = norm(imageData - compressedImage,'fro')/norm(imageData,'fro');
    imageStorage(k) = imageRanks(k)*(size(imageData,1) + size(imageData,2) + 1)/numel(imageData);
    nexttile %[output:7f7f3b63]
    imagesc(compressedImage)
    axis image off
    colormap gray
    title("Rank " + imageRanks(k))
    colorbar
end
nexttile %[output:7f7f3b63]
plot(imageRanks,imageErrors,'o-','LineWidth',1.5) %[output:7f7f3b63]
grid on %[output:7f7f3b63]
title('Relative error') %[output:7f7f3b63]
xlabel('rank') %[output:7f7f3b63]
ylabel('||A-A_r||_F / ||A||_F') %[output:7f7f3b63]
imageCompressionTable = table(imageRanks.', imageErrors.', imageStorage.', 'VariableNames', ["Rank","RelativeFrobeniusError","StorageFraction"]) %[output:99fb2e0e]
%[text] Discussion prompt: At what rank does the reconstructed image become good enough for your students' purposes, and how would you connect that visual judgment to the singular value decay and the storage fraction table?
%%
%[text] ## Teaching With Live Scripts and Copilot
%[text] The same mathematical core can become several different classroom experiences depending on the prompts, pacing, and checks you include.
%[text:table]
%[text] | Teaching goal | Live Script move | MATLAB Copilot starter prompt |
%[text] | --- | --- | --- |
%[text] | Build geometric intuition | Show a circle becoming an ellipse with annotated singular vectors | `Create a live script section that visualizes how a 2x2 matrix maps the unit circle using its SVD.` |
%[text] | Check conceptual understanding | Add short editable answer cells and a checker function | `Write three student checkpoints about rank, singular values, and reconstruction error for an SVD lesson.` |
%[text] | Connect to applications | Compare low-rank approximations of a matrix and report storage savings | `Add a section that demonstrates rank-1, rank-2, and rank-5 SVD approximations and summarizes the compression tradeoff.` |
%[text] | Connect to images | Reconstruct a grayscale image with several SVD ranks and discuss quality versus storage | `Create a live script section that uses SVD to compress a sample grayscale image and reports reconstruction error.` |
%[text] | Differentiate for course level | Ask for extensions, counterexamples, or interpretation prompts | `Generate extension questions that compare SVD with eigendecomposition for advanced linear algebra students.` |
%[text:table]
%[text] Facilitation move: after each Copilot-generated draft, ask participants what should be kept, corrected, or made more student-centered. The workflow is strongest when Copilot accelerates drafting and the educator supplies the mathematical judgment.
%%
%[text] ## Build Your Own Adaptation
%[text] Use the final minutes of the workshop to turn this example into a lesson idea for your own students.
%[text] 1. Pick one context: geometry, data compression, image compression, least squares, principal components, or image processing.
%[text] 2. Decide what students should produce: a prediction, a plot annotation, a numerical check, or a written explanation.
%[text] 3. Ask MATLAB Copilot for a first draft of one section, then revise the mathematics, examples, and prompts yourself.
%[text] 4. Keep the activity short enough that students can focus on meaning rather than mechanics. A single strong visualization plus one checkpoint is often enough.
%[text] 5. Before sharing it with students, run the script once and verify that every output supports the learning goal \
%[text] Starter prompt: `Create a Live Script section for my linear algebra class that uses the SVD to explain TOPIC with one visualization, one numerical experiment, and one student checkpoint.`
function approximation = lowRankApprox(U,S,V,r)
approximation = U(:,1:r)*S(1:r,1:r)*V(:,1:r)';
end
function checkScalar(label, studentValue, expectedValue, tolerance)
if nargin < 4
    tolerance = 1e-10;
end
if isnumeric(studentValue) && isscalar(studentValue) && isfinite(studentValue)
    if abs(studentValue - expectedValue) < tolerance
        disp(label + ": correct")
    else
        disp(label + ": not correct yet")
    end
else
    disp(label + ": enter a numeric value")
end
end

